const swampFlowerSheet=new Image();swampFlowerSheet.assetSrc='assets/swamp-flower-anim-v1.png';
function beginSwampFlower(e){let a=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.facing=Math.cos(a)-Math.sin(a)<0?-1:1;e.attack={pattern:'flowerBeds',bespoke:true,windup:.9,beds:[0,-140,140].map((offset,i)=>({x:p.x-Math.sin(a)*offset,y:p.y+Math.cos(a)*offset,at:Math.round((.9+i*.4)*1e6)/1e6,done:false})).filter(b=>lineClear(e,b))};}
const flowerAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r3e6')return flowerAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;
 e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);
 if(e.attack?.pattern!=='flowerBeds'){e.t-=dt;e.nav=(e.nav||0)-dt;let distance=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&distance<=380&&clear)beginSwampFlower(e);else{e.state='idle';if(distance>750&&!e.aware)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,50*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,22)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;let a=e.attack;for(let b of a.beds)if(!b.done&&e.elapsed>=b.at){b.done=true;if(lineClear(e,b)){if(dist(b,p)<=65&&lineClear(b,p))hurt(35);burst(b.x,b.y,65,'#d9a4e3');playSound('impact',b.x,b.y);}}
 if(e.elapsed>=2.4){e.attack=null;e.state='idle';e.t=2.2;}
};
const flowerDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r3e6'||!swampFlowerSheet.complete||!swampFlowerSheet.naturalWidth)return flowerDrawBase(e,size);let frame=spriteFrame(e.state,e.anim);if(e.attack?.pattern==='flowerBeds')frame={row:2,col:e.elapsed<.45?0:e.elapsed<.9?1:e.elapsed<1.7?2:3};let q=project(e.x,e.y),sw=swampFlowerSheet.naturalWidth/4,sh=swampFlowerSheet.naturalHeight/3,w=115,h=w*sh/sw;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,swampFlowerSheet,frame.col*sw,frame.row*sh,sw,sh,-w/2,-h*.9,w,h);else ctx.drawImage(swampFlowerSheet,frame.col*sw,frame.row*sh,sw,sh,-w/2,-h*.9,w,h);ctx.restore();return true;};
const flowerSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r3e6'?95:flowerSizeBase(e);
const flowerGroundBase=drawGroundEffects;drawGroundEffects=()=>{flowerGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r3e6'):enemies)){if(e.species!=='r3e6'||e.hp<=0||e.attack?.pattern!=='flowerBeds')continue;for(let b of e.attack.beds){if(b.done||!visibleAt(b.x,b.y))continue;groundRing(b.x,b.y,65,'#d9a4e3',3);groundRing(b.x,b.y,65*clamp(e.elapsed/b.at,0,1),'#fff1bd',2);}}};
